const item = $input.first().json;
const toolCall = item.body.message.toolCalls[0];
let args = toolCall.function.arguments;
if (typeof args === "string") { args = JSON.parse(args); }
const name = String(args.name || args.fullName || '').trim();
const firstName = name.split(/\s+/)[0] || 'there';
const confirmation = "Thanks " + firstName + ", you are all set. Your practice session is booked and your personal learning plan is on its way to your inbox.";
return [{
  json: {
    name,
    email: String(args.email || '').trim().toLowerCase(),
    skill: String(args.skill || ''),
    level: String(args.level || ''),
    hoursPerWeek: Number(args.hoursPerWeek || args.hours_per_week || 0),
    sessionDateTime: String(args.sessionDateTime || args.datetime || ''),
    confirmation
  }
}];
